#!/usr/bin/env bash
# shellcheck disable=SC1091 # Compiled CLI is generated by smoke.sh.
set -euo pipefail
ROOT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
tmpdir=$(mktemp -d)
trap 'rm -rf "$tmpdir"' EXIT
export HOME="$tmpdir/home" PLAK_NO_PATH_PRELUDE=1
mkdir -p "$HOME/.local/bin"
source "$ROOT_DIR/plak.sh" >/dev/null
export PATH="$HOME/.local/bin:/usr/bin:/bin"
printf '<?php // Test WP entry point\n' > "$HOME/.local/bin/wp"
cat > "$HOME/.local/bin/frankenphp" <<'FRANK'
#!/usr/bin/env bash
if [ "$1" = version ]; then echo 'FrankenPHP v1.12.7 PHP 8.5'; exit; fi
[ "$1" = php-cli ] || exit 89
if [[ "$2" = */probe.php ]]; then printf '%s' "${TEST_MISSING:-}"; exit "${TEST_SCRIPT_RC:-0}"; fi
echo 'SECRET_IN_EXTERNAL_DIAGNOSTIC' >&2
exit "${TEST_WP_RC:-0}"
FRANK
chmod +x "$HOME/.local/bin/"*
plak_health wordpress --json > "$tmpdir/report"
python3 - "$tmpdir/report" <<'PY'
import json,sys
r=json.load(open(sys.argv[1])); assert r['wordpress_cli']=='ready' and r['exit_code']==0
PY
rc=0
TEST_MISSING=mysqli TEST_SCRIPT_RC=69 plak_health wordpress --json > "$tmpdir/report" || rc=$?
[ "$rc" -eq 69 ]
grep -q 'mysqli' "$tmpdir/report"
rc=0
TEST_WP_RC=37 plak_health wordpress --json > "$tmpdir/report" 2> "$tmpdir/error" || rc=$?
[ "$rc" -eq 37 ]
grep -q 'wp-cli' "$tmpdir/report"
if grep -q SECRET "$tmpdir/report" "$tmpdir/error"; then exit 1; fi
rm "$HOME/.local/bin/wp"
if plak_health wordpress --json > "$tmpdir/report"; then exit 1; fi
grep -q 'unavailable' "$tmpdir/report"
echo 'WordPress health readiness/failures/exit status/secret-safe output tests passed'
